package netx

import (
	"bytes"
	"context"
	"crypto/sha256"
	"os"
	"path/filepath"
	"testing"
	"time"
)

// The normal lifecycle first writes and confirms a canonical native profile.
// Repeating that intent must exercise the distinct candidate inode even when
// every selected authored/generated byte remains identical.
func nativeFixtureEqualProfileLive(t *testing.T, ctx context.Context, s *Service, owner string, want NativeIntent) *NativeProfileView {
	t.Helper()
	read := func() *nativeProfile {
		t.Helper()
		deadline := time.Now().Add(8 * time.Second)
		var p *nativeProfile
		var err error
		for time.Now().Before(deadline) && ctx.Err() == nil {
			p, err = s.readNativeProfile(ctx, "d0")
			if err == nil && p != nil && p.View.Editable && p.View.Intent != nil && nativeIntentEqual(*p.View.Intent, want) && p.View.Configured.Status == "matching" && p.View.Runtime.Status == "matching" && p.View.Boot.Status == "matching" {
				return p
			}
			time.Sleep(100 * time.Millisecond)
		}
		if p != nil {
			t.Fatalf("%s equal-profile full owner agreement: configured=%+v runtime=%+v boot=%+v refusal=%q err=%v", owner, p.View.Configured, p.View.Runtime, p.View.Boot, p.View.Refusal, err)
		}
		t.Fatalf("%s equal-profile owner unreadable: %v", owner, err)
		return nil
	}
	apply := func() (*changeJournal, *nativeUndo) {
		t.Helper()
		prior := read()
		if _, err := s.EditNativeProfile(WithPendingConfirmation(ctx, 7), "d0", NativeEditRequest{Generation: prior.View.Generation, Intent: want}, "127.0.0.1"); err != nil {
			t.Fatalf("%s canonical unchanged-intent apply: %v", owner, err)
		}
		j, err := readChange(s.paths.Dir)
		if err != nil || j.Phase != "awaiting_confirmation" {
			t.Fatalf("%s unchanged-intent journal did not reach pending: %v", owner, err)
		}
		u, err := nativeJournalUndo(j)
		if err != nil {
			t.Fatal(err)
		}
		files := []nativeProfileFile{prior.File}
		if prior.View.Owner == "netplan" {
			files = append(files, prior.Generated)
		}
		if len(u.Files) != len(files) || !nativeIntentEqual(u.BeforeIntent, u.CandidateIntent) {
			t.Fatal("unchanged intent lost its closed selected file/intent scope")
		}
		for i, f := range u.Files {
			if f.Before.Path != files[i].Path || f.Before.Identity != files[i].Identity || !bytes.Equal(f.Before.Data, files[i].Data) || !bytes.Equal(f.Before.Data, f.Candidate.Data) || f.Before.Identity == f.Candidate.Identity {
				t.Fatalf("%s profile was not canonical with literally equal captured bytes and distinct inodes: path=%s before=%+v candidate=%+v beforeSHA=%x candidateSHA=%x", owner, f.Before.Path, f.Before.Identity, f.Candidate.Identity, sha256.Sum256(f.Before.Data), sha256.Sum256(f.Candidate.Data))
			}
			if err := nativeCurrentFile(f.Candidate, f.Candidate.Identity); err != nil {
				t.Fatalf("%s unchanged candidate did not retain its recorded inode: %v", owner, err)
			}
			displaced := f.Before
			displaced.Path = f.CandidatePath
			if err := nativeCurrentFile(displaced, f.Before.Identity); err != nil {
				t.Fatalf("%s unchanged exchange did not retain the exact authored inode: %v", owner, err)
			}
			t.Logf("%s canonical unchanged-intent path=%s SHA256=%x beforeInode=%d candidateInode=%d retainedAuthoredInode=%d", owner, f.Before.Path, sha256.Sum256(f.Before.Data), f.Before.Identity.Inode, f.Candidate.Identity.Inode, displaced.Identity.Inode)
		}
		read()
		return j, u
	}
	help := func(j *changeJournal) {
		t.Helper()
		capability, err := nativeFixtureExecute(ctx, nil, filepath.Join(s.paths.Dir, recoveryBinary), "--network-native-check")
		if err != nil || capability != "jd-native-manager-v10\n" {
			t.Fatalf("equal-profile fresh helper did not expose the exact shipped v10 capability: %q %v", capability, err)
		}
		if out, err := nativeFixtureExecute(ctx, nil, filepath.Join(s.paths.Dir, recoveryBinary), "--network-recover", s.paths.Dir, j.ID); err != nil {
			t.Fatalf("%s unchanged-intent fresh helper: %v %s", owner, err, out)
		}
	}
	j, u := apply()
	help(j)
	for _, f := range u.Files {
		if err := nativeCurrentFile(f.Before, f.Before.Identity); err != nil {
			t.Fatalf("%s equal-byte fresh rollback did not return its exact retained authored inode: path=%s inode=%d err=%v", owner, f.Before.Path, f.Before.Identity.Inode, err)
		}
	}
	p := read()
	finished, err := readChange(s.paths.Dir)
	if err != nil || finished.Phase != "recovered" {
		t.Fatalf("equal-profile fresh rollback has no durable restored decision: %v", err)
	}
	nativeAutomaticCleanup(t, ctx, s, j.ID)
	j, u = apply()
	proof, err := s.VerifyReconnection(ctx, j.ID, 7, "equal-profile-session", "127.0.0.1")
	if err != nil {
		t.Fatal(err)
	}
	status, err := s.ConfirmChange(ctx, j.ID, 7, "equal-profile-session", proof.Challenge, "127.0.0.1")
	if err != nil || status.Phase != "confirmed" || status.Cleanup != "complete" {
		t.Fatalf("equal-profile durable confirmation failed: %+v %v", status, err)
	}
	help(j)
	for _, f := range u.Files {
		if err := nativeCurrentFile(f.Candidate, f.Candidate.Identity); err != nil {
			t.Fatalf("%s confirmed equal-byte candidate inode changed during terminal helper retry: %v", owner, err)
		}
		if _, err := os.Lstat(f.CandidatePath); !os.IsNotExist(err) {
			t.Fatal("confirmed equal-profile retained stage remains", err)
		}
	}
	p = read()
	nativeAutomaticCleanup(t, ctx, s, j.ID)
	t.Logf("%s shipped helper v10 equal-byte candidate rollback restored exact authored inodes; unchanged-intent confirmation and terminal fresh-helper retry retained exact candidate inodes and full configured/runtime/boot agreement", owner)
	return &p.View
}
